function interleaving_distance(F, G):
    # F, G are weight tables indexed by subsets of the vertex set
    best <- 0
    for each simplex sigma in domain(F):
        gap <- |F[sigma] - G[sigma]|
        if gap > best:
            best <- gap
    return best   # = max_sigma |F(sigma) - G(sigma)| = d(F, G)

