function geodesic_samples(F, G, n):
    samples <- empty list
    for k in 0 .. n:
        t <- k / n
        L <- new table
        for each simplex sigma in domain(F):
            L[sigma] <- (1 - t) * F[sigma] + t * G[sigma]
        append L to samples
    return samples   # samples[0]=F, samples[n]=G, equidistant

